"""Generate the synthetic example trace corpus (deterministic).

Usage: uv run python scripts/generate_example_traces.py
Output: examples/traces/synthetic_traces.jsonl

All records are SYNTHETIC (no production data). The corpus intentionally contains defects so the
quality pipeline has something real to catch: unverified claims, duplicates, malformed JSON,
schema violations, missing provenance, orphan tool results and dangling verification references.
"""

from __future__ import annotations

import json
from pathlib import Path

PROV = {
    "provenance": "synthetic: generated by scripts/generate_example_traces.py",
    "license": "CC-BY-4.0",
    "synthetic": True,
}
T0 = "2026-01-05T10:00:00+00:00"


def ts(sec: int) -> str:
    return f"2026-01-05T10:00:{sec:02d}+00:00"


def canonical(task_id: str, outcome: str, notes: str, **extra: object) -> dict:
    steps = [
        {
            "sequence_number": 0,
            "role": "system",
            "content": "You are a security engineer.",
            "started_at": ts(0),
            "completed_at": ts(0),
        },
        {
            "sequence_number": 1,
            "role": "user",
            "content": f"Fix {task_id}. {notes}",
            "started_at": ts(1),
            "completed_at": ts(1),
        },
        {
            "sequence_number": 2,
            "role": "assistant",
            "content": "",
            "started_at": ts(2),
            "completed_at": ts(2),
            "action_type": "tool_call",
            "metadata": {
                "tool_calls": [
                    {
                        "id": "c1",
                        "type": "function",
                        "function": {"name": "read_file", "arguments": '{"path": "TASK.md"}'},
                    }
                ]
            },
        },
        {
            "sequence_number": 3,
            "role": "tool",
            "tool_name": "read_file",
            "started_at": ts(3),
            "completed_at": ts(3),
            "action_input": {"path": "TASK.md"},
            "observation": {"content": "# task"},
            "metadata": {"call_id": "c1"},
        },
        {
            "sequence_number": 4,
            "role": "assistant",
            "content": "I applied a parameterised query.",
            "started_at": ts(4),
            "completed_at": ts(4),
        },
    ]
    rec = {
        "schema_version": "1.0",
        "source_type": "synthetic",
        "task_id": task_id,
        "task_version": "1.0.0",
        "model_id": "synthetic-model",
        "started_at": T0,
        "completed_at": ts(10),
        "steps": steps,
        "outcome": outcome,
        "metadata": dict(PROV),
    }
    rec.update(extra)
    return rec


def chat(
    record_id: str, success: bool | None, provenance: bool = True, orphan: bool = False
) -> dict:
    messages = [
        {"role": "system", "content": "You fix SSRF bugs."},
        {"role": "user", "content": "Harden validate_url."},
        {
            "role": "assistant",
            "content": None,
            "tool_calls": [
                {
                    "id": "call_a",
                    "type": "function",
                    "function": {
                        "name": "read_file",
                        "arguments": '{"path": "app/image_proxy.py"}',
                    },
                }
            ],
        },
        {
            "role": "tool",
            "tool_call_id": "call_zzz" if orphan else "call_a",
            "name": "read_file",
            "content": '{"content": "def validate_url(url, resolver): ..."}',
        },
        {"role": "assistant", "content": "Done: resolver-based validation added."},
    ]
    rec: dict = {
        "id": record_id,
        "model": "imported-model",
        "task_id": "ssrf-t0-s000",
        "created": 1767607200,
        "messages": messages,
        "success": success,
    }
    if provenance:
        rec["metadata"] = dict(PROV)
    return rec


def main() -> None:
    lines: list[str] = []
    dup = canonical("sqli-t0-s000", "SUCCESS", "claimed success, never verified")
    lines.append(json.dumps(canonical("sqli-t0-s001", "FAILURE", "attempt that gave up")))
    lines.append(json.dumps(dup))
    lines.append(json.dumps(dup))  # exact duplicate (same content -> same content hash)
    lines.append(
        json.dumps(canonical("sqli-t0-s001", "FAILURE", "attempt  that   gave up"))
    )  # near-duplicate
    lines.append(json.dumps(chat("chat-001", True)))
    lines.append(
        json.dumps(chat("chat-002", None, provenance=False))
    )  # imported without provenance
    lines.append(json.dumps(chat("chat-003", False, orphan=True)))  # orphan tool result
    lines.append('{"schema_version": "1.0", "steps": [')  # malformed JSON
    bad_seq = canonical("authz-t0-s000", "UNKNOWN", "bad order")
    bad_seq["steps"][3]["sequence_number"] = 1
    lines.append(json.dumps(bad_seq))  # non-monotonic sequence -> schema invalid
    naive = canonical("authz-t0-s000", "UNKNOWN", "naive timestamps")
    naive["started_at"] = "2026-01-05T10:00:00"
    lines.append(json.dumps(naive))  # naive timestamp -> schema invalid
    lines.append(json.dumps({"foo": "bar"}))  # unknown format
    lines.append(
        json.dumps(
            canonical(
                "ssrf-t1-s000",
                "SUCCESS",
                "cites a verification that does not exist",
                verification_id="11111111-2222-3333-4444-555555555555",
            )
        )
    )
    lines.append(json.dumps(canonical("authz-t1-s002", "PARTIAL", "partial fix claimed")))
    out = Path(__file__).resolve().parents[1] / "examples" / "traces" / "synthetic_traces.jsonl"
    out.parent.mkdir(parents=True, exist_ok=True)
    out.write_text("\n".join(lines) + "\n", encoding="utf-8", newline="\n")
    print(f"wrote {len(lines)} records to {out}")


if __name__ == "__main__":
    main()
